INSERT OR IGNORE INTO instructors (id, display_name, email, department, bio, created_at, updated_at) VALUES
  ('ins_01J9ZK5A1B2C3D4E5F6G7H8J01', 'Dr. Ada Lovelace', 'ada.lovelace@example.edu', 'Computer Science', 'Mathematician and pioneer of algorithmic thinking who teaches programming and systems courses.', '2026-01-05T09:00:00Z', '2026-08-01T09:00:00Z'),
  ('ins_01J9ZK5A1B2C3D4E5F6G7H8J02', 'Dr. Alan Turing', 'alan.turing@example.edu', 'Mathematics', 'Researcher in computability and mathematical analysis with an emphasis on rigorous proof.', '2026-01-05T09:00:00Z', '2026-08-01T09:00:00Z'),
  ('ins_01J9ZK5A1B2C3D4E5F6G7H8J03', 'Dr. Katherine Johnson', 'katherine.johnson@example.edu', 'Statistics', 'Applied statistician focused on probability, inference, and computational methods for real-world data.', '2026-01-05T09:00:00Z', '2026-08-01T09:00:00Z'),
  ('ins_01J9ZK5A1B2C3D4E5F6G7H8J04', 'Dr. Florence Nightingale', 'florence.nightingale@example.edu', 'Data Science', 'Data scientist and visualization advocate who teaches reproducible analysis and machine learning.', '2026-01-05T09:00:00Z', '2026-08-01T09:00:00Z'),
  ('ins_01J9ZK5A1B2C3D4E5F6G7H8J05', 'Dr. Rosalind Franklin', 'rosalind.franklin@example.edu', 'Biology', 'Molecular biologist with research interests in DNA structure, gene expression, and laboratory methods.', '2026-01-05T09:00:00Z', '2026-08-01T09:00:00Z'),
  ('ins_01J9ZK5A1B2C3D4E5F6G7H8J06', 'Dr. Adam Smith', 'adam.smith@example.edu', 'Economics', 'Economist studying markets, incentives, and empirical methods for public policy evaluation.', '2026-01-05T09:00:00Z', '2026-08-01T09:00:00Z');

INSERT OR IGNORE INTO courses (id, code, title, description, department, level, credits, status, summary, tags, enrichment_source, published_at, created_at, updated_at) VALUES
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C01', 'CS-101', 'Introduction to Computer Science', 'Foundational course covering algorithms, abstraction, data representation, and problem solving with Python.', 'Computer Science', 'introductory', 3, 'published', 'A hands-on introduction to computational thinking and programming with Python.', '["programming","python","algorithms","foundations"]', 'ai', '2026-08-20T14:30:00Z', '2026-01-15T09:00:00Z', '2026-08-20T14:30:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C02', 'CS-201', 'Data Structures and Algorithms', 'Core data structures, algorithm analysis, recursion, sorting, graphs, and dynamic programming.', 'Computer Science', 'intermediate', 4, 'published', 'Build efficient programs using core data structures and algorithm design techniques.', '["algorithms","data structures","complexity","java"]', 'ai', '2026-08-21T10:00:00Z', '2026-01-15T09:00:00Z', '2026-08-21T10:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C03', 'CS-301', 'Operating Systems', 'Processes, threads, scheduling, memory management, file systems, and concurrency in modern kernels.', 'Computer Science', 'advanced', 4, 'published', 'Study the design and implementation of operating system kernels and concurrent systems.', '["operating systems","concurrency","memory","linux"]', 'ai', '2026-08-22T11:00:00Z', '2026-01-15T09:00:00Z', '2026-08-22T11:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C04', 'CS-401', 'Distributed Systems', 'Consistency, replication, fault tolerance, consensus, and distributed storage design.', 'Computer Science', 'advanced', 3, 'published', 'Design reliable distributed systems using replication, consensus, and fault tolerance.', '["distributed systems","consensus","replication","fault tolerance"]', 'ai', '2026-09-02T13:00:00Z', '2026-02-01T09:00:00Z', '2026-09-02T13:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C05', 'MATH-101', 'Calculus I', 'Limits, derivatives, integrals, and applications of single-variable calculus.', 'Mathematics', 'introductory', 4, 'published', 'Develop fluency with limits, derivatives, and integrals through applied problem solving.', '["calculus","limits","derivatives","integration"]', 'ai', '2026-08-18T09:30:00Z', '2026-01-15T09:00:00Z', '2026-08-18T09:30:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C06', 'MATH-201', 'Linear Algebra', 'Vector spaces, matrices, linear transformations, eigenvalues, and applications.', 'Mathematics', 'intermediate', 3, 'published', 'Understand vector spaces and matrix methods that underpin data science and engineering.', '["linear algebra","matrices","eigenvalues","vectors"]', 'ai', '2026-08-19T12:00:00Z', '2026-01-15T09:00:00Z', '2026-08-19T12:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C07', 'MATH-301', 'Real Analysis', 'Rigorous treatment of sequences, series, continuity, differentiation, and integration.', 'Mathematics', 'advanced', 4, 'published', 'Construct rigorous proofs about limits, continuity, and integration in real analysis.', '["analysis","proofs","continuity","sequences"]', 'ai', '2026-08-23T15:00:00Z', '2026-01-15T09:00:00Z', '2026-08-23T15:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C08', 'STAT-101', 'Introduction to Statistics', 'Descriptive statistics, sampling, probability basics, confidence intervals, and hypothesis testing.', 'Statistics', 'introductory', 3, 'published', 'Learn to summarize data and draw defensible conclusions using statistical inference.', '["statistics","probability","sampling","inference"]', 'ai', '2026-08-17T08:00:00Z', '2026-01-15T09:00:00Z', '2026-08-17T08:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C09', 'STAT-201', 'Probability Theory', 'Random variables, distributions, expectation, limit theorems, and stochastic modeling.', 'Statistics', 'intermediate', 4, 'published', 'Model uncertainty with random variables, distributions, and limit theorems.', '["probability","distributions","random variables","stochastic"]', 'ai', '2026-08-24T10:15:00Z', '2026-01-15T09:00:00Z', '2026-08-24T10:15:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C10', 'STAT-301', 'Statistical Inference', 'Estimation theory, hypothesis testing, likelihood methods, and asymptotic analysis.', 'Statistics', 'advanced', 4, 'published', 'Estimate parameters and evaluate hypotheses using likelihood and asymptotic theory.', '["inference","likelihood","hypothesis testing","estimation"]', 'ai', '2026-08-25T11:45:00Z', '2026-01-15T09:00:00Z', '2026-08-25T11:45:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C11', 'STAT-401', 'Applied Bayesian Modeling', 'Bayesian inference, priors, hierarchical models, MCMC, and applied case studies.', 'Statistics', 'advanced', 3, 'published', 'Apply Bayesian inference and MCMC to hierarchical models and real data problems.', '["bayesian","mcmc","modeling","statistics"]', 'ai', '2026-09-03T09:00:00Z', '2026-02-01T09:00:00Z', '2026-09-03T09:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C12', 'DATA-201', 'Data Wrangling and Visualization', 'Cleaning, transforming, and visualizing tabular data using Python and modern libraries.', 'Data Science', 'intermediate', 3, 'published', 'Turn messy datasets into clear, reproducible analyses and visualizations with Python.', '["data wrangling","python","visualization","pandas"]', 'ai', '2026-08-26T14:00:00Z', '2026-01-15T09:00:00Z', '2026-08-26T14:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C13', 'DATA-301', 'Machine Learning Foundations', 'Supervised and unsupervised learning, model evaluation, and practical machine learning pipelines.', 'Data Science', 'advanced', 4, 'published', 'Train and evaluate machine learning models with an emphasis on sound methodology.', '["machine learning","python","modeling","scikit-learn"]', 'ai', '2026-08-27T16:30:00Z', '2026-01-15T09:00:00Z', '2026-08-27T16:30:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C14', 'DATA-401', 'Deep Learning', 'Neural networks, optimization, convolutional and sequence models, and training at scale.', 'Data Science', 'advanced', 4, 'draft', 'Build and train neural networks for vision and sequence tasks using modern frameworks.', '["deep learning","neural networks","pytorch","optimization"]', 'fallback', NULL, '2026-03-01T09:00:00Z', '2026-10-15T09:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C15', 'BIO-101', 'Foundations of Biology', 'Cell biology, genetics, evolution, and ecology for students beginning the life sciences.', 'Biology', 'introductory', 4, 'published', 'Explore the core principles of life from cells and genes to ecosystems and evolution.', '["biology","cells","evolution","ecology"]', 'ai', '2026-08-16T10:00:00Z', '2026-01-15T09:00:00Z', '2026-08-16T10:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C16', 'BIO-201', 'Genetics', 'Mendelian inheritance, molecular genetics, gene expression, and genomics.', 'Biology', 'intermediate', 4, 'published', 'Connect classical inheritance with modern molecular genetics and genomic analysis.', '["genetics","inheritance","dna","genomics"]', 'ai', '2026-08-28T10:30:00Z', '2026-01-15T09:00:00Z', '2026-08-28T10:30:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C17', 'BIO-301', 'Molecular Biology', 'DNA replication, transcription, translation, regulation, and experimental techniques.', 'Biology', 'advanced', 4, 'published', 'Investigate how cells store, express, and regulate genetic information.', '["molecular biology","transcription","translation","gene regulation"]', 'ai', '2026-08-29T13:15:00Z', '2026-01-15T09:00:00Z', '2026-08-29T13:15:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C18', 'ECON-101', 'Principles of Microeconomics', 'Consumer choice, markets, supply and demand, market structures, and public policy.', 'Economics', 'introductory', 3, 'published', 'Analyze how individuals and firms make choices in markets and respond to policy.', '["microeconomics","markets","demand","policy"]', 'ai', '2026-08-15T11:00:00Z', '2026-01-15T09:00:00Z', '2026-08-15T11:00:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C19', 'ECON-201', 'Intermediate Microeconomics', 'Formal models of consumer and firm behavior, equilibrium, and welfare analysis.', 'Economics', 'intermediate', 3, 'published', 'Use formal models to explain consumer behavior, market equilibrium, and welfare.', '["microeconomics","equilibrium","welfare","modeling"]', 'ai', '2026-08-30T09:45:00Z', '2026-01-15T09:00:00Z', '2026-08-30T09:45:00Z'),
  ('crs_01J9ZK4Q7M2W8N5R3T6Y0B1C20', 'ECON-301', 'Econometrics', 'Linear regression, causal inference, panel data, and empirical research methods.', 'Economics', 'advanced', 3, 'draft', 'Estimate causal effects and test economic theories using regression and panel data.', '["econometrics","regression","causal inference","r"]', 'fallback', NULL, '2026-03-01T09:00:00Z', '2026-10-16T09:00:00Z');

